'use client';

import { TransactionsDataTable } from "./components/transactions-data-table";
import { columns } from "./components/transactions-columns";
import { NewTransactionModal } from "./components/new-transaction-modal";
import { Suspense } from "react";
import { Skeleton } from "@/components/ui/skeleton";
import { useTransactions } from "@/app/hooks/useTransactions";

function TransactionsContent() {
  // Use our custom hook instead of direct SWR usage
  const {
    transactions,
    pagination,
    isLoading,
    error,
    setPage,
    createTransaction,
    refresh
  } = useTransactions();

  // Handle new transaction creation
  const handleCreateTransaction = async (data: any) => {
    try {
      await createTransaction(data);
      // No need to refresh manually since the hook handles it
    } catch (err) {
      console.error("Failed to create transaction:", err);
    }
  };

  if (error) {
    return <div className="p-8 text-center">Failed to load transactions. Please try again.</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold">Transactions</h1>
        <NewTransactionModal onSuccess={refresh} />
      </div>

      {isLoading ? (
        <div className="space-y-4">
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-96 w-full" />
        </div>
      ) : (
        <>
          <TransactionsDataTable columns={columns} data={transactions} />
          
          {pagination.pages > 1 && (
            <div className="flex justify-center mt-4">
              <nav>
                <ul className="flex space-x-2">
                  {Array.from({ length: pagination.pages }, (_, i) => (
                    <li key={i}>
                      <button
                        onClick={() => setPage(i + 1)}
                        className={`px-3 py-1 rounded ${
                          pagination.page === i + 1
                            ? 'bg-primary text-white'
                            : 'bg-gray-200 hover:bg-gray-300'
                        }`}
                      >
                        {i + 1}
                      </button>
                    </li>
                  ))}
                </ul>
              </nav>
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default function TransactionsPage() {
  return (
    <Suspense fallback={
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-10 w-36" />
        </div>
        <Skeleton className="h-96 w-full" />
      </div>
    }>
      <TransactionsContent />
    </Suspense>
  );
} 